import sys


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    steps = [int(data[idx + i]) for i in range(k)]

    # winning[i] = True if the player to move with i stones left can win
    winning = [False] * (n + 1)
    for i in range(1, n + 1):
        for s in steps:
            if s <= i and not winning[i - s]:
                winning[i] = True
                break

    if not winning[n]:
        print("LOSE")
        return

    for s in sorted(steps):
        if s <= n and not winning[n - s]:
            print("WIN", s)
            return


main()
